// Local development and test bootstrap for the two logins and the tenant-context key. NEVER used in production:
// production passwords and the key are generated by scripts/neon-provision.ts and live in Secret Manager.
import pg from "pg";
import { createDatabase, DEV_CONTEXT_KEY, type Database } from "./client";

// va_app and va_worker are cluster-wide roles: every local suite must agree on their passwords.
export const LOCAL_APP_PASSWORD = process.env.VA_APP_LOCAL_PASSWORD ?? "va_app_local";
export const LOCAL_WORKER_PASSWORD = process.env.VA_WORKER_LOCAL_PASSWORD ?? "va_worker_local";

/** Same server and database as `url`, different login. */
export function withLogin(url: string, user: string, password: string): string {
  const u = new URL(url);
  u.username = user;
  u.password = password;
  return u.toString();
}

/** The va_worker URL that matches a local va_app URL. */
export const localSystemUrl = (appUrl: string) => withLogin(appUrl, "va_worker", LOCAL_WORKER_PASSWORD);

/**
 * Run as the database owner, after migrations: give both logins their local passwords and install the
 * development context key. Idempotent.
 */
export async function prepareLocalRoles(owner: pg.Pool | pg.Client): Promise<void> {
  // Roles are cluster-wide and suites run in parallel: concurrent ALTER ROLEs can collide ("tuple concurrently updated").
  for (const sql of [
    `ALTER ROLE va_app LOGIN PASSWORD '${LOCAL_APP_PASSWORD}'`,
    `ALTER ROLE va_worker LOGIN PASSWORD '${LOCAL_WORKER_PASSWORD}'`,
  ]) {
    for (let attempt = 1; ; attempt++) {
      try {
        await owner.query(sql);
        break;
      } catch (e) {
        const code = (e as { code?: string }).code;
        if (attempt >= 8 || (code !== "XX000" && code !== "40001" && code !== "23505")) throw e;
        await new Promise((r) => setTimeout(r, 100 * attempt));
      }
    }
  }
  await owner.query(
    `INSERT INTO app_ctx_key (singleton, key) VALUES (true, $1)
     ON CONFLICT (singleton) DO UPDATE SET key = excluded.key, rotated_at = now()`,
    [DEV_CONTEXT_KEY],
  );
}

/** `prepareLocalRoles` for a caller that only has the owner connection string (e.g. a Playwright global setup). */
export async function prepareLocalRolesAt(ownerUrl: string): Promise<void> {
  const owner = new pg.Pool({ connectionString: ownerUrl, max: 1 });
  try {
    await prepareLocalRoles(owner);
  } finally {
    await owner.end();
  }
}

/** A Database for a local va_app URL, with the matching va_worker pool and the development key. */
export function createLocalDatabase(appUrl: string, opts: { max?: number } = {}): Database {
  return createDatabase(appUrl, {
    systemUrl: localSystemUrl(appUrl),
    contextKey: DEV_CONTEXT_KEY,
    max: opts.max,
  });
}
